"""Section 11, no one-step congruence certificate.  Is W_2 = F_2 (x) rho (x) rho in the closed cone generated by the
congruences (X (x) Y)^* W_1 (X (x) Y), W_1 = F_2 (x) rho, X, Y : C^2 (x) C^9 -> C^2 (x) C^3, and positive operators?
Everything is invariant under g (x) g, g = U_0 (x) U_1 (x) U_2, so after twirling the question lives in the span of the
8 projectors Q_e (symmetric/antisymmetric on the qubit pair and on the two copy pairs).  Cutting-plane LP over the
dual: c >= 0, sum_e c_e Tr Q_e = 1, sum_e c_e Tr(G Q_e) >= 0 for the generated congruences G, minimising
sum_e c_e Tr(W_2 Q_e); the oracle minimises Tr[W_1 (X (x) Y) sigma_c (X (x) Y)^*] over unit X, Y by local search
(Adam then L-BFGS, several restarts).  A negative optimum with no violated cut is a (numerical) dual certificate.
usage: python check_congruence_lp.py rounds restarts iters   (e.g. 60 30 1200; needs PyTorch and SciPy)
"""
import sys, itertools, numpy as np, torch
from scipy.optimize import linprog
torch.set_default_dtype(torch.float64)
ROUNDS, RS, IT = (int(a) for a in sys.argv[1:4])
def swap(d):
    S = np.zeros((d * d, d * d))
    for i in range(d):
        for j in range(d): S[d * i + j, d * j + i] = 1
    return S
F2, F3 = swap(2), swap(3)
P2 = {'s': (np.eye(4) + F2) / 2, 'a': (np.eye(4) - F2) / 2}
P3 = {'s': (np.eye(9) + F3) / 2, 'a': (np.eye(9) - F3) / 2}
rho = np.eye(9) - F3 / 2
def arrange(ops, dims):
    """ops[k] acts on pair k (A_k B_k) with local dim dims[k]; return operator on (A_0 A_1 ..)(B_0 B_1 ..)."""
    m = len(ops); R = np.eye(1)
    for o in ops: R = np.kron(R, o)
    shape = []
    for d in dims: shape += [d, d]
    perm = [2 * i for i in range(m)] + [2 * i + 1 for i in range(m)]
    R = R.reshape(shape + shape).transpose(perm + [2 * m + q for q in perm])
    D = int(np.prod(dims)); return R.reshape(D * D, D * D)
labels = list(itertools.product('sa', repeat=3))
Q = [arrange([P2[e[0]], P3[e[1]], P3[e[2]]], [2, 3, 3]) for e in labels]
W1 = arrange([F2, rho], [2, 3]); W2 = arrange([F2, rho, rho], [2, 3, 3])
w = np.array([np.trace(W2 @ q) for q in Q]); trQ = np.array([np.trace(q) for q in Q])
print("labels", [''.join(e) for e in labels]); print("w =", np.round(w, 4)); print("Tr Q =", trQ)
Qt = torch.tensor(np.stack(Q), dtype=torch.complex128); W1t = torch.tensor(W1, dtype=torch.complex128)
def t_of(X, Y):
    K = torch.kron(X, Y)                                     # 36 x 324
    G = K.conj().T @ W1t @ K
    return torch.einsum('ij,eji->e', G, Qt).real
def oracle(c):
    sig = torch.tensor(np.einsum('e,eij->ij', c, np.stack(Q)), dtype=torch.complex128)
    best = (np.inf, None)
    for r in range(RS):
        torch.manual_seed(7919 * len(cuts) + r)
        X = torch.randn(6, 18, dtype=torch.complex128, requires_grad=True)
        Y = torch.randn(6, 18, dtype=torch.complex128, requires_grad=True)
        def fval():
            Xn = X / torch.linalg.norm(X); Yn = Y / torch.linalg.norm(Y)
            K = torch.kron(Xn, Yn)
            return torch.trace(W1t @ K @ sig @ K.conj().T).real
        opt = torch.optim.Adam([X, Y], lr=0.03)
        for it in range(IT):
            f = fval(); opt.zero_grad(); f.backward(); opt.step()
        opt2 = torch.optim.LBFGS([X, Y], lr=1, max_iter=400, line_search_fn='strong_wolfe', tolerance_grad=1e-14, tolerance_change=1e-16)
        def cl():
            opt2.zero_grad(); v = fval(); v.backward(); return v
        opt2.step(cl)
        f = fval()
        if f.item() < best[0]: best = (f.item(), ((X / torch.linalg.norm(X)).detach().clone(), (Y / torch.linalg.norm(Y)).detach().clone()))
    return best
rng = np.random.default_rng(0)
cuts = []
for _ in range(40):
    X = torch.tensor(rng.standard_normal((6, 18)) + 1j * rng.standard_normal((6, 18)))
    Y = torch.tensor(rng.standard_normal((6, 18)) + 1j * rng.standard_normal((6, 18)))
    cuts.append(t_of(X, Y).numpy())
for rd in range(ROUNDS):
    A_ub = -np.array(cuts); b_ub = np.zeros(len(cuts))
    res = linprog(w, A_ub=A_ub, b_ub=b_ub, A_eq=trQ[None, :], b_eq=[1.0], bounds=[(0, None)] * 8, method='highs')
    c = res.x
    val, XY = oracle(c)
    print(f"round {rd}: LP value {res.fun:+.5e} | c = {np.round(c, 5)} | oracle min {val:+.3e}", flush=True)
    if val > -1e-9:
        print("no violated cut found: candidate dual certificate (CD would be FALSE if the oracle is right)" if res.fun < -1e-9
              else "LP value >= 0: no dual certificate found (CD not refuted)", flush=True)
        break
    cuts.append(t_of(*XY).numpy() / max(1e-12, np.abs(t_of(*XY).numpy()).max()))
np.save("cd_lp_c.npy", c)
